from __future__ import annotations
from dataclasses import dataclass
from typing import Callable


@dataclass(frozen=True)
class Formula:
    kind: str   # "inst" | "atLeast"
    value: int


def inst(n: int) -> Formula: return Formula("inst", n)
def atLeast(k: int) -> Formula: return Formula("atLeast", k)


@dataclass(frozen=True)
class ProofSys:
    proofs: tuple
    concl: Callable[[object], Formula]

    def provable(self, f: Formula) -> bool:
        return any(self.concl(p) == f for p in self.proofs)


def bounded_dark(k: int) -> ProofSys:
    return ProofSys(tuple(range(k + 1)), lambda j: atLeast(j))


def no_instance(s: ProofSys, upto: int = 40) -> bool:
    return all(not s.provable(inst(n)) for n in range(upto + 1))


def dark_at_level(s: ProofSys, k: int) -> bool:
    return s.provable(atLeast(k)) and no_instance(s)


if __name__ == "__main__":
    for k in range(1, 6):
        b = bounded_dark(k)
        print(f"B_{k}: dark of level {k}? {dark_at_level(b, k)};  "
              f"dark of level {k+1}? {dark_at_level(b, k+1)}")

"""Join amplification: dark(a) join dark(b) is dark of level max(a, b)."""
from __future__ import annotations
from dataclasses import dataclass
from typing import Callable


@dataclass(frozen=True)
class Formula:
    kind: str
    value: int


def inst(n: int) -> Formula: return Formula("inst", n)
def atLeast(k: int) -> Formula: return Formula("atLeast", k)


@dataclass(frozen=True)
class ProofSys:
    proofs: tuple
    concl: Callable[[object], Formula]

    def provable(self, f: Formula) -> bool:
        return any(self.concl(p) == f for p in self.proofs)


def bounded_dark(k: int) -> ProofSys:
    return ProofSys(tuple(range(k + 1)), lambda j: atLeast(j))


def join(s: ProofSys, t: ProofSys) -> ProofSys:
    tagged = tuple(("L", p) for p in s.proofs) + tuple(("R", p) for p in t.proofs)
    return ProofSys(tagged,
                    lambda tp: s.concl(tp[1]) if tp[0] == "L" else t.concl(tp[1]))


def darkness_level(s: ProofSys, max_k: int = 40) -> int:
    top = max((k for k in range(max_k + 1) if s.provable(atLeast(k))), default=-1)
    names_none = all(not s.provable(inst(n)) for n in range(max_k + 1))
    return top if names_none else -1


if __name__ == "__main__":
    for a, b in [(1, 3), (2, 2), (4, 1), (0, 5)]:
        lvl = darkness_level(join(bounded_dark(a), bounded_dark(b)))
        print(f"B_{a} join B_{b}: level {lvl} (expected max = {max(a, b)})")

"""Vanishing uniform density of dark configurations: (N-1)/(N*2^N) -> 0."""
from __future__ import annotations
from fractions import Fraction


def dark_density(N: int) -> Fraction:
    """Configurations = top-level in {0..N-1} x instance-pattern in {0,1}^N.
    Dark = top-level >= 1 AND all-false pattern (unique). Density -> 0."""
    total = N * (2 ** N)
    dark = N - 1
    return Fraction(dark, total)


if __name__ == "__main__":
    for N in [2, 4, 8, 16, 32, 64]:
        d = dark_density(N)
        print(f"N={N:>3}: density = {float(d):.3e}")

